DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `calcular_area_circulo`(
    IN radio DOUBLE,
    OUT area DOUBLE
)
BEGIN
    SET area = PI() * POW(radio, 2);
END ;;
