CREATE DEFINER=`root`@`localhost` PROCEDURE `calcular_max_min_media`(
    OUT maximo DECIMAL(15,2),
    OUT minimo DECIMAL(15,2),
    OUT media DECIMAL(15,2)
)
BEGIN
    SELECT MAX(precio), MIN(precio), AVG(precio)
    INTO maximo, minimo, media
    FROM productos;
END ;;
