CREATE DEFINER=`root`@`localhost` PROCEDURE `calcular_volumen_cilindro`(
    IN radio DOUBLE,
    IN altura DOUBLE,
    OUT volumen DOUBLE
)
BEGIN
    DECLARE area DOUBLE;
    CALL calcular_area_circulo(radio, area);
    SET volumen = area * altura;
END ;;
