CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ValidarLoginHash`(
    IN _dsUsuario  VARCHAR(50),
    IN _dsPassword VARCHAR(50)
)
BEGIN
    SELECT
        id,
        dsId,
        dsUsuario,
        dsPassword,
        dsEstado,
        dsUsuarioCreacion,
        dtFechaCreacion
    FROM usuarios
    WHERE dsUsuario  = _dsUsuario
      AND dsPassword = UNHEX(SHA2(_dsPassword, 512))
      AND dsEstado   = '1';
END ;;
